e, NULL AS return_date, CASE WHEN UPPER(\"MP Name\") = \'SHOPIFY\' AND UPPER(\"Component SKU Category\") LIKE \'%PACKAGING MATERIAL%\' THEN \'Shopify Gift Box\' ELSE \"MP Name\" END AS marketplace_name, \"MP Name\" AS marketplace_name_raw, \"Sales Channel\" AS sales_channel, \"Component SKU Name\" AS product_name, \"Component SKU Brand\" AS brand, \"Component SKU Category\" AS category, \"Suborder No\" AS suborder_id, TRY_TO_NUMBER(\"Item Quantity\") AS quantity, TRY_TO_NUMBER(\"Component SKU MRP\") AS mrp, TRY_TO_NUMBER(\"Selling Price\") AS selling_price, TRY_TO_NUMBER(\"Component SKU Cost\") AS cost_price, CASE WHEN UPPER(\"MP Name\") = \'AJIO DROPSHIP\' THEN TRY_TO_NUMBER(\"Taxable Value\") * 1.30 ELSE TRY_TO_NUMBER(\"Taxable Value\") END AS taxable_value, CASE WHEN UPPER(\"MP Name\") = \'AJIO DROPSHIP\' THEN TRY_TO_NUMBER(CGST) * 1.30 ELSE TRY_TO_NUMBER(CGST) END AS cgst, CASE WHEN UPPER(\"MP Name\") = \'AJIO DROPSHIP\' THEN TRY_TO_NUMBER(SGST) * 1.30 ELSE TRY_TO_NUMBER(SGST) END AS sgst, CASE WHEN UPPER(\"MP Name\") = \'AJIO DROPSHIP\' THEN TRY_TO_NUMBER(IGST) * 1.30 ELSE TRY_TO_NUMBER(IGST) END AS igst, CASE WHEN UPPER(\"MP Name\") = \'AJIO DROPSHIP\' THEN TRY_TO_NUMBER(CESS) * 1.30 ELSE TRY_TO_NUMBER(CESS) END AS cess, \'Regular\' AS order_classification, \"Order Type\" AS order_type, \"Order Status\" AS order_status, \"Invoice Status\" AS invoice_status, \"Payment Mode\" AS payment_mode, CASE WHEN \"MP Name\" IN (\'Flipkart\', \'Amazon Smart Connect\', \'Myntra PPMP\', \'Myntra Jabong India Pvt Ltd\', \'AJIO Dropship\', \'Nykaa\', \'Nykaa Fashion\', \'TaTa Cliq\', \'TataCliq Luxury\', \'Zilo Retail Pvt Ltd\') THEN \'3P\' ELSE \'Direct.com\' END AS channel_type, \'SALES\' AS transaction_type, NULL AS credit_note_id, \"EE Invoice No\" AS ee_invoice_no, DISCOUNT_CODE, case when not(lower(ifnull(DISCOUNT_CODE,\'\')) in (\'moc\',\'mog\',\'challan\')) then 1 else 0 end as Discount_Flag FROM ANDAMEN_DB.MAPLEMONK.ANDAMEN_EASYECOM_TAX_SALES TS left join ( SELECT nam