t Mode\" AS payment_mode, CASE WHEN \"MP Name\" IN (\'Flipkart\', \'Amazon Smart Connect\', \'Myntra PPMP\', \'Myntra Jabong India Pvt Ltd\', \'AJIO Dropship\', \'Nykaa\', \'Nykaa Fashion\', \'TaTa Cliq\', \'TataCliq Luxury\', \'Zilo Retail Pvt Ltd\') THEN \'3P\' ELSE \'Direct.com\' END AS channel_type, \'RETURN\' AS transaction_type, \"Credit Note ID\" AS credit_note_id, \"EE Invoice No\" AS ee_invoice_no, DISCOUNT_CODE, case when not(lower(ifnull(DISCOUNT_CODE,\'\')) in (\'moc\',\'mog\',\'challan\')) then 1 else 0 end as Discount_Flag, FROM ANDAMEN_DB.MAPLEMONK.ANDAMEN_EASYECOM_TAX_RETURNS TS left join ( SELECT name AS Order_Name, upper(B.VALUE:code::String) AS DISCOUNT_CODE FROM andamen_db.maplemonk.shopify_andamen_website_orders,LATERAL FLATTEN (INPUT => DISCOUNT_CODES)B qualify row_number() over(partition by lower(trim(name)) order by 1) = 1 )ds on trim(lower(ts.\"Reference Code\")) = trim(lower(ds.Order_Name)) WHERE \"Order Type\" != \'STN\' AND lower(\"Invoice Status\") not like \'%cancel%\' AND lower(\"Order Status\") not like \'%cancel%\' AND \"Item Quantity\" IS NOT NULL ), combined_data AS ( SELECT * FROM sales_raw UNION ALL SELECT * FROM returns_raw ), with_mappings AS ( SELECT c.transaction_date, c.return_date, c.marketplace_name, c.marketplace_name_raw, COALESCE(ch.channel_name, c.marketplace_name) AS channel_name, CASE WHEN COALESCE(d.door_name, \'3P\') like \'%Shopify%\' THEN \'DotCom\' WHEN COALESCE(d.door_name, \'3P\') = \'3P\' THEN \'3P\' ELSE \'3P\' END AS door_name, c.sales_channel, c.product_name, c.brand, c.category, c.suborder_id, c.quantity, c.mrp, c.selling_price, c.cost_price, c.taxable_value, c.cgst, c.sgst, c.igst, c.cess, c.order_classification, c.order_type, c.order_status, c.invoice_status, c.payment_mode, c.channel_type, c.transaction_type, c.credit_note_id, c.ee_invoice_no FROM combined_data c LEFT JOIN ANDAMEN_DB.MAPLEMONK.MAPPING_CHANNEL_NAMES ch ON c.marketplace_name = ch.mp_name LEFT JOIN ANDAMEN_DB.MAPLEMONK.MAPPING_DOOR_NAMES 